// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"IB Physics Theme A covers motion: how things move and why. It's the foundation for everything else.","blocks":[{"t":"key","text":"Kinematics (SUVAT for constant acceleration): v = u + at, s = ut + ½at², v² = u² + 2as, s = ½(u + v)t. Projectiles: horizontal and vertical motion are independent."},{"t":"p","text":"Newton's laws: F = ma (more generally F = Δp/Δt). Momentum p = mv is conserved in isolated systems. Impulse = FΔt = Δp."},{"t":"p","text":"Circular motion: centripetal acceleration a = v²/r = ω²r toward the center."},{"t":"ex","problem":"A car accelerates from 10 m/s to 25 m/s in 5 s. Find its acceleration and displacement.","steps":["a = (25 − 10)/5 = 3 m/s²"],"answer":"s = ½(10 + 25)(5) = 87.5 m"}]},{"say":"Energy is conserved, but it changes form. And at very high speeds, Einstein's relativity takes over.","blocks":[{"t":"key","text":"Work W = Fs cos θ. Kinetic energy Eₖ = ½mv² = p²/2m. Gravitational potential energy ΔEₚ = mgΔh. Elastic potential energy Eₕ = ½kx². Power P = W/t = Fv. Efficiency = useful output/input."},{"t":"p","text":"Energy is conserved in isolated systems; friction transfers energy to thermal energy."},{"t":"p","text":"HL adds rigid body mechanics (torque, moment of inertia, angular momentum) and special relativity: time dilation, length contraction and the invariance of the speed of light."},{"t":"ex","problem":"A 60 kg runner climbs 10 m of stairs in 12 s. Find her power output.","steps":["ΔEₚ = 60 × 9.8 × 10 = 5,880 J"],"answer":"P = 5,880/12 = 490 W"}]}],[{"say":"Theme B explains matter in terms of particles: heat, temperature, gases and even Earth's climate.","blocks":[{"t":"key","text":"Temperature measures average kinetic energy of particles. Specific heat capacity: Q = mcΔT. Specific latent heat (phase changes): Q = mL."},{"t":"p","text":"Heat transfer: conduction, convection and radiation. A black body emits radiation with power P = σAT⁴ (Stefan–Boltzmann law); Wien's law: λₘₐₓT = 2.9 × 10⁻³ m K."},{"t":"p","text":"The greenhouse effect: Earth absorbs short-wavelength solar radiation and emits infrared; greenhouse gases absorb and re-emit infrared, warming the surface. Albedo is the fraction of radiation reflected."},{"t":"p","text":"Ideal gas law: pV = nRT. Kinetic theory links pressure to particle collisions."}]},{"say":"Electric circuits are also part of Theme B, since current is the flow of charged particles.","blocks":[{"t":"key","text":"Current I = ΔQ/Δt. Potential difference V = W/q. Resistance R = V/I; resistivity R = ρL/A. Power P = IV = I²R = V²/R."},{"t":"p","text":"Series circuits: same current, voltages add, R = R₁ + R₂. Parallel circuits: same voltage, currents add, 1/R = 1/R₁ + 1/R₂."},{"t":"p","text":"Cells have emf ε and internal resistance r: ε = I(R + r). Ohmic conductors follow V ∝ I at constant temperature; filament lamps and diodes are non-ohmic."},{"t":"ex","problem":"A 12 V battery with internal resistance 1 Ω drives a 5 Ω resistor. Find the current.","steps":["I = ε/(R + r) = 12/6"],"answer":"2 A"}]}],[{"say":"Theme C covers oscillations and waves, from pendulums to sound and light.","blocks":[{"t":"key","text":"Simple harmonic motion: acceleration is proportional to displacement and opposite in direction: a = −ω²x. Period of a pendulum T = 2π√(l/g); mass on a spring T = 2π√(m/k)."},{"t":"p","text":"Waves transfer energy without transferring matter. v = fλ. Transverse waves oscillate perpendicular to travel; longitudinal waves oscillate parallel (sound)."},{"t":"p","text":"Electromagnetic waves travel at c = 3.00 × 10⁸ m/s in a vacuum and can be polarized (transverse only)."},{"t":"ex","problem":"A wave has frequency 500 Hz and wavelength 0.68 m. Find its speed.","steps":["v = fλ = 500 × 0.68"],"answer":"340 m/s"}]},{"say":"Waves reflect, refract, diffract and interfere. These behaviors explain rainbows, echoes and radar.","blocks":[{"t":"key","text":"Snell's law: n₁ sin θ₁ = n₂ sin θ₂. Total internal reflection occurs above the critical angle. Diffraction is greatest when the gap is similar to the wavelength."},{"t":"p","text":"Interference: constructive when path difference = nλ; destructive when path difference = (n + ½)λ. Double-slit fringe spacing s = λD/d."},{"t":"p","text":"Standing waves form from two waves traveling in opposite directions, creating nodes and antinodes. On a string, λ = 2L/n."},{"t":"p","text":"Doppler effect: a moving source or observer changes the observed frequency; approaching raises it, receding lowers it. It's used in radar speed guns and to measure redshift of galaxies."}]}],[{"say":"Theme D describes forces that act at a distance through fields: gravity, electricity and magnetism.","blocks":[{"t":"key","text":"Newton's law of gravitation: F = GMm/r². Gravitational field strength g = GM/r². Orbital speed v = √(GM/r). Kepler's third law: T² ∝ r³."},{"t":"p","text":"Coulomb's law: F = kq₁q₂/r². Electric field strength E = F/q; between parallel plates E = V/d."},{"t":"p","text":"Field lines show direction and strength (closer lines = stronger field)."},{"t":"p","text":"HL adds gravitational and electric potential and potential energy, escape velocity and equipotentials."},{"t":"ex","problem":"If the distance between two masses triples, how does the gravitational force change?","steps":["F ∝ 1/r²"],"answer":"It becomes 1/9 as strong"}]},{"say":"Moving charges create magnetic fields and feel magnetic forces. Changing fields induce currents.","blocks":[{"t":"key","text":"Force on a moving charge: F = qvB sin θ. Force on a current-carrying wire: F = BIL sin θ. Charged particles in uniform magnetic fields move in circles: r = mv/(qB)."},{"t":"p","text":"Magnetic fields around wires and solenoids follow the right-hand grip rule."},{"t":"p","text":"HL: electromagnetic induction. Magnetic flux Φ = BA cos θ. Faraday's law: ε = −N ΔΦ/Δt. Lenz's law: the induced current opposes the change that caused it. Generators and transformers rely on induction."},{"t":"ex","problem":"A proton moves at 2 × 10⁶ m/s perpendicular to a 0.5 T field. Is the force on it doing work?","steps":["The magnetic force is perpendicular to velocity"],"answer":"No; it changes direction but not speed"}]}],[{"say":"Theme E explores the atom and nucleus, where classical physics breaks down.","blocks":[{"t":"key","text":"Atomic spectra show discrete energy levels: a photon's energy E = hf equals the difference between levels. The photoelectric effect (HL) shows light's particle nature: Eₖmax = hf − Φ."},{"t":"p","text":"Radioactive decay is random and spontaneous. Alpha (helium nucleus), beta-minus (electron and antineutrino), beta-plus (positron and neutrino) and gamma (photon) decay. Half-life is the time for half the nuclei to decay. Activity A = λN."},{"t":"ex","problem":"A sample has a half-life of 3 days. What fraction remains after 9 days?","steps":["9 days = 3 half-lives"],"answer":"(1/2)³ = 1/8"}]},{"say":"Nuclear reactions power reactors and stars by converting mass into energy.","blocks":[{"t":"key","text":"E = mc². The mass defect (difference between the mass of separate nucleons and the nucleus) equals the binding energy divided by c². Binding energy per nucleon peaks near iron-56, so fission of heavy nuclei and fusion of light nuclei both release energy."},{"t":"p","text":"Fission: a neutron splits uranium-235 into smaller nuclei and more neutrons, allowing a chain reaction. Reactors use moderators (slow neutrons), control rods (absorb neutrons) and coolant."},{"t":"p","text":"Fusion powers stars. A star's life cycle depends on its mass; the Hertzsprung–Russell diagram plots luminosity against temperature."}]}]];
export default text;
